const finalQuestions=[{module:'passwords',q:'Un compañero pide tu contraseña por una urgencia. ¿Qué hacés?',o:['La comparto por cinco minutos','Indico el proceso oficial de recuperación','Le presto mi sesión abierta'],a:1},{module:'data',q:'¿Dónde compartís una planilla con datos sensibles?',o:['En una nube personal','Por mensajería','Solo en una plataforma corporativa autorizada'],a:2},{module:'grooming',q:'Ante pedidos de secretos, fotos y aislamiento, ¿qué corresponde?',o:['Guardar evidencia y pedir ayuda','Continuar para conocer la intención','Borrar todo de inmediato'],a:0},{module:'email',q:'Un correo urgente pide tus credenciales. ¿Qué hacés?',o:['Lo reporto y no interactúo','Respondo para verificar','Abro el enlace en incógnito'],a:0},{module:'threats',q:'Un mensaje de texto con un enlace falso para robar datos es…',o:['Vishing','Smishing','Ransomware'],a:1},{module:'social',q:'Al alejarte de tu escritorio, la acción segura es…',o:['Bloquear la pantalla','Dejar todo abierto','Compartir la sesión'],a:0},{module:'passwords',q:'Recibís una aprobación de segundo factor que no solicitaste. ¿Cuál es la mejor respuesta?',o:['Aprobarla si aparece varias veces para que deje de insistir','Rechazarla y reportar o verificar el intento por el canal oficial','Compartir el código con soporte para que revise el caso'],a:1},{module:'data',q:'Un cliente solicita datos por un canal distinto al habitual. ¿Qué decisión protege mejor la información?',o:['Enviar solo una parte de los datos para responder rápido','Validar identidad, necesidad y canal autorizado antes de compartir','Reenviar el pedido a una cuenta personal para consultarlo desde casa'],a:1},{module:'email',q:'Un proveedor conocido envía un archivo inesperado desde una dirección levemente distinta. ¿Qué hacés?',o:['Lo abrís porque el nombre del proveedor coincide','Verificás el pedido por un canal independiente antes de abrirlo','Lo reenviás al equipo para que alguien más lo pruebe'],a:1},{module:'threats',q:'Un equipo muestra archivos con extensiones desconocidas y un aviso de pago. ¿Qué acción inicial es más adecuada?',o:['Seguir trabajando y reiniciar al finalizar el día','Aislar o reportar el equipo según el procedimiento de incidentes','Pagar de inmediato para recuperar los archivos'],a:1}];
const hangmanWords=[{word:'RANSOMWARE',definition:'Tipo de software malicioso que bloquea o cifra información y exige un pago para recuperarla.'},{word:'PHISHING',definition:'Engaño que busca obtener credenciales o datos mediante mensajes, sitios o enlaces falsos.'},{word:'MALWARE',definition:'Término general para programas diseñados para dañar, alterar o acceder sin autorización a un equipo.'}];
const $=s=>document.querySelector(s); const clone=id=>$('#'+id).content.cloneNode(true); const pointsPill=points=>`<span class="points-pill">${points} pts</span>`;
function readSavedUser(){try{return JSON.parse(localStorage.getItem('cq_demo_session')||sessionStorage.getItem('cq_demo_session')||'null')}catch{try{localStorage.removeItem('cq_demo_session');sessionStorage.removeItem('cq_demo_session')}catch{}return null}}
function shuffledOptions(options,key){let hash=0;for(const char of key)hash=(hash*31+char.charCodeAt(0))>>>0;const shift=hash%options.length;return options.map((text,index)=>({text,index,order:(index+shift)%options.length})).sort((a,b)=>a.order-b.order)}
function celebrate(){const layer=document.createElement('div');layer.className='celebration';['✦','★','🎉','✦','✨','🎊','★'].forEach((symbol,i)=>{const bit=document.createElement('span');bit.className='confetti';bit.textContent=symbol;bit.style.setProperty('--x',`${(i-3)*62}px`);bit.style.setProperty('--y',`${-80-(i%3)*55}px`);layer.append(bit)});document.body.append(layer);setTimeout(()=>layer.remove(),900)}
function playUnlockSound(){try{const Ctx=window.AudioContext||window.webkitAudioContext,ctx=new Ctx(),now=ctx.currentTime;[440,660,880].forEach((freq,index)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=freq;osc.type='sine';gain.gain.setValueAtTime(.0001,now+index*.12);gain.gain.exponentialRampToValueAtTime(.13,now+index*.12+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+index*.12+.28);osc.connect(gain).connect(ctx.destination);osc.start(now+index*.12);osc.stop(now+index*.12+.3)});setTimeout(()=>ctx.close(),900)}catch{}}
function showUnlockCinematic(title){const layer=document.createElement('div');layer.className='unlock-cinematic';const stars=document.createElement('div');stars.className='unlock-stars';for(let i=0;i<28;i++){const star=document.createElement('span');star.className='unlock-star';star.textContent=i%4===0?'★':'✦';star.style.setProperty('--left',`${Math.random()*100}%`);star.style.setProperty('--delay',`${Math.random()*.65}s`);star.style.setProperty('--duration',`${1.05+Math.random()*.8}s`);star.style.setProperty('--size',`${10+Math.random()*18}px`);stars.append(star)}layer.append(stars);layer.insertAdjacentHTML('beforeend',`<div>✦ Misión superada<small>${title} se convierte en un logro de piedra</small></div>`);document.body.append(layer);setTimeout(()=>layer.remove(),2100)}
function updateHeader(){const pct=Math.round(state.completed.size/modules.length*100);$('#score').textContent=state.score;$('#globalProgress').style.width=pct+'%';$('#globalProgressText').textContent=pct+'%';$('#logoutBtn').classList.toggle('hidden',!state.user)}
function isUnlocked(i){return state.user?.role==='admin'||i===0||state.completed.has(orderedModules[i-1].id)}
function renderDashboard(){app.replaceChildren(clone('dashboardTemplate'));const grid=$('#moduleGrid'),admin=state.user?.role==='admin',finalUnlocked=state.score>=720;orderedModules.forEach((m,i)=>{const done=state.completed.has(m.id),open=isUnlocked(i),card=document.createElement('article'),stage=!open?'locked':done?'stone':'ready';card.className='module-card '+stage;card.innerHTML=`<div class="module-glow" aria-hidden="true"></div><div class="card-icon">${done?'🔓':open?m.icon:'🔒'}</div><p class="module-state">${done?'Misión superada':open?'Misión disponible':'Misión bloqueada'}</p><h3>${m.title}</h3><p>${open?m.subtitle:'Completá el módulo anterior para iluminar este desafío.'}</p><div class="card-footer">${done?'<span class="badge">✓ Aprobado</span>':open?`<span>Meta: ${pointsPill(passScores[m.id])}</span>`:'<span>🔒 Bloqueado</span>'}<button class="start" ${open?'data-module="'+m.id+'"':'disabled'}>${done?'Repasar →':open?'Comenzar →':'🔒'}</button></div>`;grid.append(card)});const final=document.createElement('section');final.className='final-banner final-gold '+(finalUnlocked||admin?'':'final-locked');final.innerHTML=`<div class="gold-bar" aria-hidden="true"><span>AU</span></div><div class="final-copy"><p class="eyebrow">${admin&&!finalUnlocked?'MODO ADMINISTRADOR · PRUEBA':finalUnlocked?'RECOMPENSA DESBLOQUEADA':'RECOMPENSA BLOQUEADA'}</p><h2>Desafío final</h2><p>Combiná los seis temas para conquistar el gran lingote de oro.</p><small>Necesitás al menos <b>720 pts</b> para desbloquearlo.</small></div><button class="primary" ${finalUnlocked||admin?'data-action="final"':'disabled'}>${finalUnlocked||admin?'Desbloquear →':'🔒 720 pts'}</button>`;grid.after(final);if(admin){const panel=document.createElement('section');panel.className='admin-panel';panel.innerHTML=`<p class="eyebrow">ADMINISTRACIÓN</p><h2>Autorizar admin</h2><form id="promoteForm"><input name="email" type="email" placeholder="Email de la cuenta" required><button class="primary">Autorizar</button></form><small id="promoteResult"></small>`;(document.querySelector('.challenge-banner')||final).after(panel);$('#promoteForm').onsubmit=promoteAdmin}$('#moduleCounter').textContent=`${state.completed.size} de ${modules.length} aprobados`;updateHeader();focusApp()}
function renderLanding(){renderDashboard();$('.section-head').remove();$('#moduleGrid').remove();$('.challenge-banner').remove();$('.final-banner').remove();$('.reset-link').remove();document.querySelector('.admin-panel')?.remove();const benefits=document.createElement('section');benefits.className='landing-benefits';benefits.innerHTML=`<p class="eyebrow">UNA CULTURA DE SEGURIDAD</p><h2>Aprender haciendo cambia los hábitos.</h2><p>CyberQuest transforma conceptos de ciberseguridad en decisiones concretas para que las personas reconozcan riesgos, cuiden la información y actúen con confianza.</p><div class="benefit-grid"><article><span>🎯</span><h3>Situaciones reales</h3><p>Decisiones basadas en el día a día laboral.</p></article><article><span>🧩</span><h3>Aprendizaje activo</h3><p>Trivias, desafíos y juegos que refuerzan cada concepto.</p></article><article><span>🛡️</span><h3>Empresas más seguras</h3><p>Una experiencia medible para prevenir errores y fraudes.</p></article></div></section>`;$('.hero').after(benefits);focusApp()}
function renderModule(id,step=0){const m=modules.find(x=>x.id===id);if(!isUnlocked(orderedModules.indexOf(m)))return;state.moduleSteps[id]=step;app.replaceChildren(clone('moduleTemplate'));$('#moduleHeader').innerHTML=`<div class="card-icon">${m.icon}</div><div><h1>${m.title}</h1><p>${m.subtitle}</p></div>`;const labels=['1. Aprendé','2. Decidí','3. Aprendé','4. Decidí','5. Trivia','6. Aprendé','7. Trivia'];labels.forEach((l,i)=>{const b=document.createElement('button');b.className='step '+(i===step?'active':'');b.textContent=l;b.disabled=state.user?.role!=='admin'&&i>step;b.onclick=()=>renderModule(id,i);$('#stepper').append(b)});const box=$('#activity');if(step===0)renderLearn(box,m,0);if(step===1)renderScenario(box,m,0);if(step===2)renderLearn(box,m,1);if(step===3)renderScenario(box,m,1);if(step===4)renderQuiz(box,m,0,0);if(step===5)renderLearn(box,m,2);if(step===6)renderQuiz(box,m,0,1);updateHeader();focusApp()}
function renderLearn(box,m,phase){const c=miniChallengeFor(m,phase),details=learnDetails[m.id]||[],pointGroups=[[0],[1,2],[3]],phaseDetails=phase===2?details.slice(2):[details[phase]],phasePoints=pointGroups[phase].map(i=>m.learn.points[i]).filter(Boolean),nextSteps=[1,3,6],nextLabels=['Ir a la situación →','Ver la próxima situación →','Ir a la trivia final →'];box.innerHTML=`<article class="activity-card"><p class="eyebrow">CONTENIDO EDUCATIVO · BLOQUE ${phase+1} DE 3</p><h2>${phase===0?m.learn.title:phase===1?'Profundizá el concepto':'Llevá el conocimiento a la práctica'}</h2>${phase===0?`<p>${m.learn.intro}</p>`:''}<div class="learn-details">${phaseDetails.map(text=>`<p>${text}</p>`).join('')}</div><div class="learning-points">${phasePoints.map(x=>`<div class="learning-point"><b>${x[0]}</b><span>${x[1]}</span></div>`).join('')}</div><section class="mini-challenge"><p class="eyebrow">MINI DESAFÍO · PRACTICÁ LO APRENDIDO</p><h3>${c.prompt}</h3><div class="options">${shuffledOptions(c.options,c.prompt).map(({text,index})=>`<button class="option" data-mini="${index}">${text}</button>`).join('')}</div><div class="mini-feedback"></div></section><div class="activity-footer"><button class="primary" id="nextActivity" disabled>${nextLabels[phase]}</button></div></article>`;box.querySelectorAll('[data-mini]').forEach(b=>b.onclick=()=>answerMini(b,c,m,nextSteps[phase]))}
function answerMini(button,c,m,nextStep){const correct=+button.dataset.mini===c.answer;document.querySelectorAll('[data-mini]').forEach(b=>{b.disabled=true;if(+b.dataset.mini===c.answer)b.classList.add('correct')});if(!correct)button.classList.add('wrong');$('.mini-feedback').innerHTML=`<div class="feedback ${correct?'good':'bad'}"><b>${correct?'¡Muy bien! ':'Para recordar: '}</b>${c.feedback}</div>`;$('#nextActivity').disabled=false;$('#nextActivity').onclick=()=>renderModule(m.id,nextStep)}
function scenarioNarrative(text){const quote=text.match(/^(.*?):\s*[“"](.+?)[”"]$/);return quote?`<p class="scenario-context">${quote[1]}:</p><div class="chat-bubble">${quote[2]}</div>`:`<p class="scenario-context">${text}</p>`}
function renderScenario(box,m,index){const s=index?extraActivities[m.id].scenario:m.scenario,visual=s.image?`<img src="${s.image}" alt="${s.person||'Personaje de la situación'}">`:`<div class="scenario-visual" aria-hidden="true">${s.visual}</div>`;box.innerHTML=`<article class="activity-card"><p class="eyebrow">SITUACIÓN DE TRABAJO ${pointsPill(20)}</p><h2>${s.title}</h2><div class="scenario with-person">${visual}<div class="scenario-content">${scenarioNarrative(s.text)}</div></div><div class="options">${shuffledOptions(s.options,s.title).map(({text,index})=>`<button class="option" data-answer="${index}">${text}</button>`).join('')}</div><div id="feedback"></div></article>`;box.querySelectorAll('.option').forEach(b=>b.onclick=()=>answerScenario(b,m,index))}
function answerScenario(button,m,index){const s=index?extraActivities[m.id].scenario:m.scenario,correct=+button.dataset.answer===s.answer,box=$('#activity'),next=index?4:2;box.querySelectorAll('.option').forEach(b=>{b.disabled=true;if(+b.dataset.answer===s.answer)b.classList.add('correct')});if(!correct)button.classList.add('wrong');if(correct){state.score+=20;state.moduleScores[m.id]=(state.moduleScores[m.id]||0)+20;celebrate()}$('#feedback').innerHTML=`<div class="feedback ${correct?'good':'bad'}"><b>${correct?'¡Buena decisión! ':'Veamos por qué. '}</b>${s.feedback}${correct?' '+pointsPill(20):''}</div><div class="activity-footer"><button class="primary" id="goQuiz">${index?'Ir a la trivia →':'Continuar aprendiendo →'}</button></div>`;$('#goQuiz').onclick=()=>renderModule(m.id,next);updateHeader()}
function renderQuiz(box,m,index,round){const quiz=round?extraActivities[m.id].quiz:m.quiz,q=quiz[index];box.innerHTML=`<article class="activity-card"><p class="eyebrow">TRIVIA ${pointsPill(40)} · ${index+1} DE ${quiz.length}</p><h2>${q[0]}</h2><div class="options">${shuffledOptions(q[1],q[0]).map(({text,index},position)=>`<button class="option" data-answer="${index}">${String.fromCharCode(65+position)}. ${text}</button>`).join('')}</div><div id="feedback"></div></article>`;box.querySelectorAll('.option').forEach(b=>b.onclick=()=>answerQuiz(b,m,index,round))}
function answerQuiz(button,m,index,round){const quiz=round?extraActivities[m.id].quiz:m.quiz,q=quiz[index],correct=+button.dataset.answer===q[2];document.querySelectorAll('.option').forEach(b=>{b.disabled=true;if(+b.dataset.answer===q[2])b.classList.add('correct')});if(!correct)button.classList.add('wrong');if(correct){state.score+=40;state.moduleScores[m.id]=(state.moduleScores[m.id]||0)+40;celebrate()}$('#feedback').innerHTML=`<div class="feedback ${correct?'good':'bad'}"><b>${correct?'¡Correcto! ':'Respuesta correcta. '}</b>${q[3]}${correct?' '+pointsPill(40):''}</div><div class="activity-footer"><button class="primary" id="nextQuestion">${index<quiz.length-1?'Siguiente pregunta →':round?'Ver resultado del módulo ✓':'Seguir aprendiendo →'}</button></div>`;$('#nextQuestion').onclick=()=>index<quiz.length-1?renderQuiz($('#activity'),m,index+1,round):round?completeModule(m):renderModule(m.id,5);updateHeader()}
function completeModule(m){const points=state.moduleScores[m.id]||0,minimum=passScores[m.id],passed=points>=minimum;if(passed){state.completed.add(m.id);playUnlockSound();showUnlockCinematic(m.title)}$('#activity').innerHTML=`<article class="activity-card completion"><div class="big">${passed?'🏆':'📘'}</div><p class="eyebrow">${passed?'MÓDULO APROBADO':'AÚN NO APROBADO'}</p><h2>${pointsPill(points)} de este módulo</h2><p>${passed?`Superaste la meta de ${pointsPill(minimum)} en <b>${m.title}</b>. El próximo módulo ya está desbloqueado.`:`Necesitás ${pointsPill(minimum)} para aprobar. Repasá el contenido y volvé a intentarlo.`}</p><button class="primary" ${passed?'data-action="modules"':'id="retryModule"'}>${passed?'Ver mis módulos':'Reintentar módulo'}</button></article>`;if(!passed)$('#retryModule').onclick=()=>{state.moduleScores[m.id]=0;renderModule(m.id,0)};updateHeader()}
function renderFinalChallenge(index=0,answers=[]){app.replaceChildren(clone('moduleTemplate'));$('#moduleHeader').innerHTML=`<div class="card-icon">🏆</div><div><h1>Desafío final</h1><p>Una evaluación integral de los seis módulos.</p></div>`;$('#stepper').remove();const item=finalQuestions[index],m=modules.find(x=>x.id===item.module);$('#activity').innerHTML=`<article class="activity-card"><p class="eyebrow">DESAFÍO FINAL · ${index+1} DE ${finalQuestions.length}</p><p class="question-count">Tema: ${m.icon} ${m.title}</p><h2>${item.q}</h2><div class="options">${shuffledOptions(item.o,item.q).map(({text,index},position)=>`<button class="option" data-final="${index}">${String.fromCharCode(65+position)}. ${text}</button>`).join('')}</div><div id="feedback"></div></article>`;document.querySelectorAll('[data-final]').forEach(b=>b.onclick=()=>answerFinal(b,item,index,answers))}
function answerFinal(button,item,index,answers){const correct=+button.dataset.final===item.a;document.querySelectorAll('[data-final]').forEach(b=>{b.disabled=true;if(+b.dataset.final===item.a)b.classList.add('correct')});if(!correct)button.classList.add('wrong');const next=[...answers,correct];$('#feedback').innerHTML=`<div class="feedback ${correct?'good':'bad'}"><b>${correct?'¡Correcto! ':'Respuesta a reforzar. '}</b>${correct?'Reconociste la práctica segura.':'Revisá este concepto antes de continuar.'}</div><div class="activity-footer"><button class="primary" id="nextFinal">${index<finalQuestions.length-1?'Siguiente desafío →':'Ver mi resultado final →'}</button></div>`;$('#nextFinal').onclick=()=>index<finalQuestions.length-1?renderFinalChallenge(index+1,next):renderFinalResult(next)}
function renderFinalResult(answers){const score=Math.round(answers.filter(Boolean).length/finalQuestions.length*100),weak=finalQuestions.find((_,i)=>!answers[i]),weakModule=weak&&modules.find(m=>m.id===weak.module);$('#activity').innerHTML=`<article class="activity-card completion"><div class="big">${score>=80?'🏆':'📘'}</div><p class="eyebrow">RESULTADO INTEGRAL</p><h2>${score}% de respuestas correctas</h2><p>${score>=80?'Excelente desempeño: aplicaste prácticas seguras en la mayoría de las situaciones.':`Área recomendada para reforzar: <b>${weakModule.icon} ${weakModule.title}</b>. Repasá ese módulo para afianzar el concepto.`}</p><div class="result-grid">${modules.map(m=>{const i=finalQuestions.findIndex(q=>q.module===m.id);return `<span>${answers[i]?'✓':'⚠'} ${m.title}</span>`}).join('')}</div><button class="primary" data-action="modules">Ver mis módulos</button></article>`;focusApp()}
function newHangman(){const item=hangmanWords[Math.floor(Math.random()*hangmanWords.length)];state.hangman={...item,guessed:[],errors:0,finished:false};renderHangman();$('#definition').insertAdjacentHTML('afterbegin','<span class="threat-icon">🦠</span>')}
function renderHangman(){if(!state.hangman)newHangman();app.replaceChildren(clone('hangmanTemplate'));const h=state.hangman;$('#definition').innerHTML=`<b>Definición:</b> ${h.definition}`;$('#word').textContent=[...h.word].map(l=>h.guessed.includes(l)?l:'_').join(' ');$('#mistakes').textContent=h.errors;const set='ABCDEFGHIJKLMNÑOPQRSTUVWXYZ';for(const l of set){const b=document.createElement('button');b.className='letter';b.textContent=l;b.disabled=h.guessed.includes(l)||h.finished;b.onclick=()=>guess(l);$('#letters').append(b)};$('.gallows').classList.add('error-'+h.errors);if(h.finished){const won=h.word.split('').every(l=>h.guessed.includes(l));$('.gallows-card').classList.add(won?'won':'lost');$('#gameMessage').innerHTML=won?'¡Concepto descubierto! '+pointsPill(20):'La palabra era '+h.word+'. ¡Probá otra!'}updateHeader();focusApp()}
function guess(letter){const h=state.hangman;if(h.finished)return;h.guessed.push(letter);if(!h.word.includes(letter))h.errors++;if(h.word.split('').every(l=>h.guessed.includes(l))){h.finished=true;state.score+=20}else if(h.errors>=5)h.finished=true;renderHangman()}
function focusApp(){setTimeout(()=>app.focus(),0)}
function renderAuth(message='',mode='login'){$('#logoutBtn').classList.add('hidden');const register=mode==='register',savedEmail=localStorage.getItem('cq_saved_email')||'';app.innerHTML=`<section class="auth-card auth-single"><p class="eyebrow">CYBERQUEST · ACCESO SEGURO</p><h1>${register?'Creá tu cuenta':'Ingresá a tu recorrido'}</h1><p>${register?'Completá tus datos para comenzar.':'Entrená con situaciones reales y protegé la información.'}</p>${message?`<div class="auth-message">${message}</div>`:''}<div class="auth-grid"><form id="authForm"><h2>${register?'Registrate':'Iniciar sesión'}</h2>${register?'<input name="name" autocomplete="name" placeholder="Nombre y apellido" required>':''}<input name="email" type="email" autocomplete="username" value="${savedEmail}" placeholder="Email" required><input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="8" placeholder="Contraseña (mín. 8 caracteres)"':'placeholder="Contraseña"'} required>${register?'':`<label class="remember-option"><input name="remember" type="checkbox" checked> Mantener mi sesión iniciada</label><label class="remember-option"><input name="rememberEmail" type="checkbox" checked> Recordar mi email</label><p class="password-note">Tu navegador puede ofrecer guardar la contraseña de forma segura.</p>`}<button class="primary">${register?'Crear cuenta':'Ingresar'}</button><p class="auth-switch">${register?'¿Ya tenés una cuenta?':'¿No tenés cuenta?'} <button type="button" id="switchAuth">${register?'Iniciá sesión':'Registrate'}</button></p></form></div></section>`;$('#authForm').onsubmit=e=>submitAuth(e,register?'/api/register':'/api/login');$('#switchAuth').onclick=()=>renderAuth('',register?'login':'register')}
function localAuth(data,url){const users=JSON.parse(localStorage.getItem('cq_demo_users')||'[]'),email=String(data.email||'').trim().toLowerCase();const demo=users.find(u=>u.email==='admin@cyberquest.demo');if(demo){demo.name='Administrador';demo.role='admin';demo.password='admin123'}else users.push({id:'cq-demo-admin',name:'Administrador',email:'admin@cyberquest.demo',password:'admin123',role:'admin'});if(url.includes('register')){if(users.some(u=>u.email===email))throw new Error('Ese email ya está registrado. Iniciá sesión con esa cuenta.');const user={id:crypto.randomUUID(),name:String(data.name||'').trim(),email,password:data.password,role:'user'};users.push(user);localStorage.setItem('cq_demo_users',JSON.stringify(users));localStorage.setItem('cq_demo_session',JSON.stringify(user));return {user}}const user=users.find(u=>u.email===email&&u.password===data.password);if(!user)throw new Error('Email o contraseña incorrectos.');const storage=data.remember?localStorage:sessionStorage;localStorage.removeItem('cq_demo_session');sessionStorage.removeItem('cq_demo_session');storage.setItem('cq_demo_session',JSON.stringify(user));if(data.rememberEmail)localStorage.setItem('cq_saved_email',email);else localStorage.removeItem('cq_saved_email');localStorage.setItem('cq_demo_users',JSON.stringify(users));return {user}}
async function submitAuth(event,url){event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form));data.email=String(data.email||'').trim().toLowerCase();data.remember=Boolean(data.remember);data.rememberEmail=Boolean(data.rememberEmail);try{let result;if(state.localMode)result=localAuth(data,url);else{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});result=await response.json();if(!response.ok)throw new Error(result.error);if(data.rememberEmail)localStorage.setItem('cq_saved_email',data.email);else localStorage.removeItem('cq_saved_email')}if(result.user){state.user=result.user;renderDashboard()}else renderAuth(result.message)}catch(error){renderAuth(error.message)}}
async function promoteAdmin(event){event.preventDefault();const email=new FormData(event.currentTarget).get('email'),result=await fetch('/api/admin/promote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})}).then(r=>r.json());$('#promoteResult').textContent=result.message||result.error}
async function logout(){if(state.localMode){localStorage.removeItem('cq_demo_session');sessionStorage.removeItem('cq_demo_session')}else await fetch('/api/logout',{method:'POST'});state.user=null;state.score=0;state.completed.clear();renderAuth('Sesión cerrada correctamente.')}
async function initialize(){const savedUser=readSavedUser();if(location.protocol==='file:'){state.localMode=true;state.user=savedUser;return state.user?renderDashboard():renderAuth('Modo demostración: las cuentas se guardan solo en este navegador.')}try{const response=await fetch('./api/session');if(!response.ok)throw new Error('Sesión no disponible');const session=await response.json();state.user=session.user;if(!state.user)return renderAuth();renderDashboard()}catch{state.localMode=true;state.user=savedUser;return state.user?renderDashboard():renderAuth('Modo demostración: las cuentas se guardan solo en este navegador.')}}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-module]');if(!btn)return;if(btn.dataset.module)renderModule(btn.dataset.module);const a=btn.dataset.action;if(a==='dashboard')renderLanding();if(a==='continue'||a==='modules')renderDashboard();if(a==='hangman')newHangman();if(a==='newWord')newHangman();if(a==='final')renderFinalChallenge();if(a==='reset'){state.score=0;state.completed.clear();state.moduleSteps={};renderDashboard()}});
document.querySelector('#homeBtn').onclick=()=>state.user?renderLanding():renderAuth();initialize().catch(()=>{state.localMode=true;state.user=null;renderAuth('No se pudo restaurar una sesión anterior. Ingresá o registrate para continuar.')});
$('#logoutBtn').onclick=logout;
